const PAGE = 20;
let shown = 0;

const fmtDate = s => {
  const [d, t] = s.split(' ');
  const dt = new Date(d + 'T00:00:00');
  return dt.toLocaleDateString('en-GB', {weekday:'long', day:'numeric', month:'long', year:'numeric'}) + ' at ' + t;
};
const fmtDur = s => { const h = Math.floor(s/3600), m = Math.floor(s%3600/60), x = s%60;
  return h ? `${h}h ${String(m).padStart(2,'0')}m` : `${m}m ${String(x).padStart(2,'0')}s`; };
const fmtPace = (d, s) => { const p = s / (d/1000); return `${Math.floor(p/60)}:${String(Math.round(p%60)).padStart(2,'0')} /km`; };

function trace(track){
  const W = 640, H = 220, pad = 22;
  const lat0 = track.reduce((a,p)=>a+p[0],0)/track.length, k = Math.cos(lat0*Math.PI/180);
  const xs = track.map(p=>p[1]*k), ys = track.map(p=>p[0]);
  const minx=Math.min(...xs), maxx=Math.max(...xs), miny=Math.min(...ys), maxy=Math.max(...ys);
  const sc = Math.min((W-2*pad)/(maxx-minx||1e-6), (H-2*pad)/(maxy-miny||1e-6));
  const ox = (W - (maxx-minx)*sc)/2, oy = (H - (maxy-miny)*sc)/2;
  const P = xs.map((x,i)=>[(ox+(x-minx)*sc).toFixed(1), (H-oy-(ys[i]-miny)*sc).toFixed(1)]);
  const pts = P.map(p=>p.join(',')).join(' ');
  const s = P[0], e = P[P.length-1];
  return `<svg class="map" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Route map">
    <polyline points="${pts}" fill="none" stroke="var(--bg)" stroke-opacity=".55" stroke-width="7" stroke-linejoin="round" stroke-linecap="round"/>
    <polyline points="${pts}" fill="none" stroke="var(--route)" stroke-width="3.2" stroke-linejoin="round" stroke-linecap="round"/>
    <circle cx="${e[0]}" cy="${e[1]}" r="6" fill="var(--end)" stroke="var(--card)" stroke-width="2.5"/>
    <circle cx="${s[0]}" cy="${s[1]}" r="6" fill="var(--start)" stroke="var(--card)" stroke-width="2.5"/>
  </svg>`;
}

const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const initials = n => n.replace(/[^A-Za-z ]/g,' ').trim().split(/\s+/).map(w=>w[0]).join('').slice(0,2).toUpperCase();
const ICON = {
  Run: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="14" cy="4.5" r="1.8"/><path d="M8 21l3-6 3 2v5M6 12l3-4 4 1 3 4 3 1"/></svg>',
  Hike: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 20l6-10 4 6 3-4 5 8z"/></svg>'
};
const SVG_KUDOS = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 11v9H4v-9zM7 11l4-8c1.5 0 2.5 1 2.5 2.5V9H19a2 2 0 0 1 2 2.3l-1.3 7A2 2 0 0 1 17.7 20H7"/></svg>';
const SVG_CMT = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12z"/></svg>';

function card(a){
  const c = COMMENTS[a.id] || [];
  const kudos = 4 + (a.id * 7919 % 23);
  return `<article class="card act">
    <div class="act-h">
      <div class="mini" aria-hidden="true">JH</div>
      <div><div class="who">Jamie H.</div><div class="when">${fmtDate(a.local)}</div></div>
      <span class="kind">${ICON[a.kind] || ICON.Run}${esc(a.kind)}</span>
    </div>
    <h4 class="title">${esc(a.title)}</h4>
    <div class="stats">
      <div><b>${(a.dist/1000).toFixed(2)}<small>km</small></b>Distance</div>
      <div><b>${fmtPace(a.dist,a.dur).replace(' /km','<small>/km</small>')}</b>Pace</div>
      <div><b>${fmtDur(a.dur)}</b>Time</div>
      ${a.indoor ? '' : `<div><b>${a.elev}<small>m</small></b>Elev gain</div>`}
      <div><b>${a.hr}<small>bpm</small></b>Avg HR</div>
    </div>
    ${a.indoor ? '<div class="map indoor"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 11l9-7 9 7v9H3z"/></svg>Indoor activity, no GPS</div>' : trace(a.track)}
    ${c.length ? `<div class="comments">${c.map(x=>`<div class="cmt"><span class="ca" aria-hidden="true">${initials(x[0])}</span><div class="cb"><b>${esc(x[0])}</b>${esc(x[1])}</div></div>`).join('')}</div>` : ''}
    <div class="foot"><button type="button" class="kudos" aria-pressed="false" data-n="${kudos}">${SVG_KUDOS}<span>${kudos}</span> kudos</button><button type="button" data-mock-title="Log in to comment" data-mock="Guests can read comments but not add them.">${SVG_CMT}${c.length} comment${c.length===1?'':'s'}</button></div>
  </article>`;
}

const feed = document.getElementById('feed');
const monthSel = document.getElementById('monthSel');
const monthName = m => new Date(m + '-01T00:00:00').toLocaleDateString('en-GB', {month:'long', year:'numeric'});
[...new Set(ACTS.map(a => a.local.slice(0, 7)))].forEach(m => {
  const o = document.createElement('option');
  o.value = m; o.textContent = `${monthName(m)} (${ACTS.filter(a => a.local.startsWith(m)).length})`;
  monthSel.appendChild(o);
});
let list = ACTS, lastMonth = '';
function render(){
  const next = list.slice(shown, shown + PAGE);
  let html = '';
  next.forEach(a => {
    const m = a.local.slice(0, 7);
    if (m !== lastMonth) { html += `<h3 class="month-h">${monthName(m)}</h3>`; lastMonth = m; }
    html += card(a);
  });
  feed.insertAdjacentHTML('beforeend', html);
  shown += next.length;
  document.getElementById('moreBtn').hidden = shown >= list.length;
}
monthSel.addEventListener('change', () => {
  list = monthSel.value ? ACTS.filter(a => a.local.startsWith(monthSel.value)) : ACTS;
  shown = 0; lastMonth = '';
  feed.replaceChildren();
  render();
});

document.getElementById('n-acts').textContent = ACTS.length;
document.getElementById('n-km').textContent = Math.round(ACTS.reduce((s,a)=>s+a.dist,0)/1000).toLocaleString('en-GB');
document.getElementById('moreBtn').addEventListener('click', render);
feed.addEventListener('click', e => {
  const k = e.target.closest('.kudos'); if (!k) return;
  const on = k.getAttribute('aria-pressed') !== 'true';
  k.setAttribute('aria-pressed', String(on));
  k.querySelector('span').textContent = Number(k.dataset.n) + (on ? 1 : 0);
});
document.querySelector('[data-top]').addEventListener('click', () => window.scrollTo({top: 0, behavior: 'smooth'}));
render();
